SELECT USU.id_usuario AS "IdUsuario",USU.id_empresa AS "IdEmpresa",USU.clave_provisoria AS "ClaveProvisoria", USU.fecha_clave_provisoria AS "FechaClaveProvisoria", USU.intentos_conexion_clave_provisoria AS "IntentosConexionClaveProvisoria", CON.valor AS "CantidadIntentosMaximo" FROM t_pla_acc_usuario AS USU LEFT JOIN t_pla_pla_configuracion AS CON ON CON.codigo_parametro = 'PLA.ClaveUsuarioIntentos' AND CON.id_empresa = USU.id_empresa WHERE USU.codigo_usuario = :CodigoUsuario LIMIT 1